"""标准 10x MatrixMarket 稀疏输入读取与严格校验。

输入目录须含三个文件：
- ``matrix.mtx``：MatrixMarket 坐标格式，仅接受
  ``coordinate integer general`` 或 ``coordinate real general``；
  行是基因、列是细胞、索引从 1 开始；零值可省略，显式值必须能
  无损解析为有限非负整数；
- ``barcodes.tsv``：每个非空行是一个细胞 ID，按文件行序进入分析；
- ``features.tsv``：每个非空数据行取第一列作为基因 ID，按文件行序进入分析。

声明维度必须与 ID 数量匹配；缺文件、格式头不支持、越界索引、重复坐标、
空或重复 ID、非法数值一律抛 :class:`cell_flow.errors.CellFlowInputError`。
"""

import hashlib
import os
from decimal import Decimal, InvalidOperation
from typing import Dict, List, Optional, Tuple

from .errors import CellFlowInputError
from .io import ExpressionMatrix, InputFile

MATRIX_NAME = "matrix.mtx"
BARCODES_NAME = "barcodes.tsv"
FEATURES_NAME = "features.tsv"

_BANNER = "%%matrixmarket"


def _fail(message: str):
    raise CellFlowInputError(message)


def _read_file(directory: str, name: str) -> Tuple[bytes, str]:
    path = os.path.join(directory, name)
    if not os.path.exists(path):
        _fail(f"MTX 输入缺少文件：{path}")
    if not os.path.isfile(path):
        _fail(f"MTX 输入路径不是普通文件：{path}")
    if not os.access(path, os.R_OK):
        _fail(f"MTX 输入文件不可读：{path}")
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError as exc:
        _fail(f"MTX 输入文件不可读：{path}（{exc}）")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        _fail(f"MTX 输入文件不是合法的 UTF-8 文本：{path}")
    return raw, text


def _read_id_lines(
    text: str,
    path: str,
    *,
    first_column_only: bool,
    kind: str,
) -> List[str]:
    """读取 ID 列表。

    barcodes：每个非空行整体是一个细胞 ID；
    features：每个非空数据行取第一列作为基因 ID。
    空行跳过，空 ID 与重复 ID 均非法。ID 按文件行序排列。
    """
    ids: List[str] = []
    seen = set()
    for line_no, line in enumerate(text.splitlines(), start=1):
        if line == "":
            continue
        token = line.split("\t", 1)[0] if first_column_only else line
        if token == "":
            _fail(f"{path} 第 {line_no} 行{kind} ID 为空")
        if token in seen:
            _fail(f"{kind} ID 重复：{token!r}")
        seen.add(token)
        ids.append(token)
    return ids


def _parse_nonnegative_integer(
    token: str, field_type: str, entry_no: int
) -> Optional[int]:
    """把一个显式矩阵元素解析为有限非负整数，要求无损。

    integer 字段只接受十进制非负整数字面量；real 字段接受浮点写法，
    但数值必须有限、非负且与其取整结果严格相等（无损）。
    返回 None 表示该元素是可省略的零。
    """
    if field_type == "integer":
        if not _is_decimal_uint(token):
            _fail(
                f"{MATRIX_NAME} 第 {entry_no} 个数据元素 {token!r} "
                f"不是非负整数"
            )
        value = int(token)
    else:  # real
        # 用 Decimal 精确解析，避免经 float64 在 2^53 以上发生舍入而
        # 破坏“无损”；显式值必须有限、非负且恰为整数
        try:
            number = Decimal(token)
        except InvalidOperation:
            number = Decimal("nan")
        if not number.is_finite():
            _fail(
                f"{MATRIX_NAME} 第 {entry_no} 个数据元素 {token!r} "
                f"不是有限数值"
            )
        if number < 0:
            _fail(
                f"{MATRIX_NAME} 第 {entry_no} 个数据元素 {token!r} 为负数"
            )
        if number != number.to_integral_value():
            _fail(
                f"{MATRIX_NAME} 第 {entry_no} 个数据元素 {token!r} "
                f"不是整数值，无法无损解析为计数"
            )
        value = int(number)
    if value == 0:
        return None
    return value


def _is_decimal_uint(token: str) -> bool:
    if not token:
        return False
    # 拒绝前导符号、小数点、指数、空白等；仅接受 0 或非零开头的十进制数
    if token == "0":
        return True
    if token[0] == "0" or not token[0].isdigit():
        return False
    return all(ch.isdigit() for ch in token)


def _parse_matrix(
    text: str, path: str
) -> Tuple[int, int, Dict[Tuple[int, int], int]]:
    lines = text.splitlines()

    # 1) 校验 banner 头
    if not lines:
        _fail(f"{path} 为空，缺少 MatrixMarket 头部")
    header_tokens = lines[0].split()
    if not header_tokens or header_tokens[0].lower() != _BANNER:
        _fail(
            f"{path} 格式头不支持：首行必须以 {_BANNER!r} 开头，"
            f"得到 {lines[0]!r}"
        )
    header = [t.lower() for t in header_tokens]
    # 标准 object/format/field/symmetry 五个关键字
    if len(header) != 5:
        _fail(f"{path} 格式头不支持：关键字数量不是 5：{lines[0]!r}")
    _, object_, format_, field_type, symmetry = header
    if object_ != "matrix":
        _fail(f"{path} 格式头不支持：object 必须是 matrix，得到 {object_!r}")
    if format_ != "coordinate":
        _fail(
            f"{path} 格式头不支持：仅接受 coordinate 格式，得到 {format_!r}"
        )
    if field_type not in ("integer", "real"):
        _fail(
            f"{path} 格式头不支持：仅接受 integer 或 real 字段，"
            f"得到 {field_type!r}"
        )
    if symmetry != "general":
        _fail(
            f"{path} 格式头不支持：仅接受 general 对称性，得到 {symmetry!r}"
        )

    # 2) 跳过注释、找到尺寸行
    body_index = 1
    dimensions: Optional[List[str]] = None
    while body_index < len(lines):
        stripped = lines[body_index].strip()
        body_index += 1
        if stripped == "":
            continue
        if stripped.startswith("%"):
            continue
        dimensions = stripped.split()
        break
    if dimensions is None:
        _fail(f"{path} 缺少维度声明行（rows columns entries）")
    if len(dimensions) != 3:
        _fail(
            f"{path} 维度声明行需要 3 个整数（rows columns entries），"
            f"得到 {dimensions!r}"
        )
    dims: List[int] = []
    for label, token in zip(("rows", "columns", "entries"), dimensions):
        if not _is_decimal_uint(token) or int(token) < 0:
            _fail(f"{path} 维度声明 {label} 不是非负整数：{token!r}")
        dims.append(int(token))
    n_rows, n_cols, n_entries = dims

    # 3) 逐行解析坐标元素
    # entries 只存非零值；seen_coords 记录全部已出现坐标（含显式零），
    # 以便对零值重复坐标同样报“重复坐标”
    entries: Dict[Tuple[int, int], int] = {}
    seen_coords = set()
    entry_no = 0
    data_seen = 0
    # lines[body_index] 即维度行之后的第一行，其 1 基行号为 body_index + 1
    for line_no, raw_line in enumerate(lines[body_index:], start=body_index + 1):
        stripped = raw_line.strip()
        if stripped == "" or stripped.startswith("%"):
            continue
        entry_no += 1
        parts = stripped.split()
        if len(parts) != 3:
            _fail(
                f"{path} 第 {line_no} 行数据需要 3 列"
                f"（row column value），得到 {len(parts)} 列"
            )
        row_tok, col_tok, val_tok = parts
        if not _is_decimal_uint(row_tok) or not _is_decimal_uint(col_tok):
            _fail(
                f"{path} 第 {line_no} 行坐标不是正整数："
                f"{row_tok!r}, {col_tok!r}"
            )
        row_idx = int(row_tok)
        col_idx = int(col_tok)
        if row_idx < 1 or row_idx > n_rows:
            _fail(
                f"{path} 第 {entry_no} 个数据元素行索引 {row_idx} 越界"
                f"（声明行数 {n_rows}）"
            )
        if col_idx < 1 or col_idx > n_cols:
            _fail(
                f"{path} 第 {entry_no} 个数据元素列索引 {col_idx} 越界"
                f"（声明列数 {n_cols}）"
            )
        value = _parse_nonnegative_integer(val_tok, field_type, entry_no)
        key = (row_idx, col_idx)
        if key in seen_coords:
            _fail(
                f"{path} 出现重复坐标（行 {row_idx}、列 {col_idx}）"
            )
        seen_coords.add(key)
        data_seen += 1
        if value is not None:
            entries[key] = value

    if data_seen != n_entries:
        _fail(
            f"{path} 实际数据元素 {data_seen} 个与声明 {n_entries} 个不一致"
        )

    return n_rows, n_cols, entries


def read_mtx_directory(directory: str) -> ExpressionMatrix:
    """读取并严格校验一个 10x MatrixMarket 目录。"""
    if directory is None or directory == "":
        _fail("输入路径为空")
    if not os.path.exists(directory):
        _fail(f"MTX 输入目录不存在：{directory}")
    if not os.path.isdir(directory):
        _fail(f"MTX 输入路径不是目录：{directory}")

    matrix_raw, matrix_text = _read_file(directory, MATRIX_NAME)
    barcodes_raw, barcodes_text = _read_file(directory, BARCODES_NAME)
    features_raw, features_text = _read_file(directory, FEATURES_NAME)

    cell_ids = _read_id_lines(
        barcodes_text,
        os.path.join(directory, BARCODES_NAME),
        first_column_only=False,
        kind="细胞",
    )
    gene_ids = _read_id_lines(
        features_text,
        os.path.join(directory, FEATURES_NAME),
        first_column_only=True,
        kind="基因",
    )
    if not cell_ids:
        _fail(f"{BARCODES_NAME} 没有任何非空细胞 ID 行")
    if not gene_ids:
        _fail(f"{FEATURES_NAME} 没有任何非空基因 ID 数据行")

    n_rows, n_cols, entries = _parse_matrix(
        matrix_text, os.path.join(directory, MATRIX_NAME)
    )
    if n_rows != len(gene_ids):
        _fail(
            f"{MATRIX_NAME} 声明行数 {n_rows} 与 {FEATURES_NAME} 基因数 "
            f"{len(gene_ids)} 不一致"
        )
    if n_cols != len(cell_ids):
        _fail(
            f"{MATRIX_NAME} 声明列数 {n_cols} 与 {BARCODES_NAME} 细胞数 "
            f"{len(cell_ids)} 不一致"
        )

    # 以基因/ID 行序展开为稠密计数矩阵，缺失坐标即零
    counts: List[List[int]] = [[0] * n_cols for _ in range(n_rows)]
    total = 0
    for (row_idx, col_idx), value in entries.items():
        counts[row_idx - 1][col_idx - 1] = value
        total += value

    files = [
        InputFile(name=MATRIX_NAME, sha256=hashlib.sha256(matrix_raw).hexdigest()),
        InputFile(name=BARCODES_NAME, sha256=hashlib.sha256(barcodes_raw).hexdigest()),
        InputFile(name=FEATURES_NAME, sha256=hashlib.sha256(features_raw).hexdigest()),
    ]
    return ExpressionMatrix(
        gene_ids=gene_ids,
        cell_ids=cell_ids,
        counts=counts,
        sha256=files[0].sha256,
        path=directory,
        total_counts=total,
        input_format="mtx",
        files=files,
    )

"""输入矩阵读取与严格校验。

输入为制表符分隔矩阵：首列是唯一基因 ID，其余列名是唯一细胞 ID，
取值为非负整数 UMI 计数。任何不合法情形都抛出
:class:`cell_flow.errors.CellFlowInputError`。
"""

import hashlib
import os
import re
from dataclasses import dataclass, field
from typing import List

from .errors import CellFlowInputError

_INTEGER_RE = re.compile(r"^(0|[1-9][0-9]*)$")


@dataclass(frozen=True)
class InputFile:
    """一个输入文件的来源记录：文件名与原始字节的 SHA-256。"""

    name: str
    sha256: str


@dataclass(frozen=True)
class ExpressionMatrix:
    """原始计数矩阵（行＝基因，列＝细胞）。

    ``input_format`` 为 ``"tsv"`` 时沿用 ``path``/``sha256`` 单一文件记录；
    为 ``"mtx"`` 时 ``files`` 依次记录 matrix.mtx、barcodes.tsv、features.tsv。
    """

    gene_ids: List[str]
    cell_ids: List[str]
    counts: List[List[int]]  # counts[gene_index][cell_index]
    sha256: str
    path: str
    total_counts: int
    input_format: str = "tsv"
    files: List[InputFile] = field(default_factory=list)

    @property
    def n_genes(self) -> int:
        return len(self.gene_ids)

    @property
    def n_cells(self) -> int:
        return len(self.cell_ids)


def _fail(message: str) -> None:
    raise CellFlowInputError(message)


def _parse_count(raw: str, gene_id: str, cell_id: str, row_no: int) -> int:
    if not _INTEGER_RE.match(raw):
        _fail(
            f"计数非法（第 {row_no} 行基因 {gene_id!r}、细胞 {cell_id!r}）："
            f"{raw!r} 不是非负整数"
        )
    return int(raw)


def read_matrix(path: str) -> ExpressionMatrix:
    if path is None or path == "":
        _fail("输入路径为空")
    if not os.path.exists(path):
        _fail(f"输入文件不存在：{path}")
    if not os.path.isfile(path):
        _fail(f"输入路径不是普通文件：{path}")
    if not os.access(path, os.R_OK):
        _fail(f"输入文件不可读：{path}")

    try:
        with open(path, "rb") as handle:
            raw_bytes = handle.read()
    except OSError as exc:
        _fail(f"输入文件不可读：{path}（{exc}）")

    digest = hashlib.sha256(raw_bytes).hexdigest()
    try:
        text = raw_bytes.decode("utf-8")
    except UnicodeDecodeError:
        _fail(f"输入文件不是合法的 UTF-8 文本：{path}")

    # splitlines 同时兼容 \n 与 \r\n，且不会因末尾换行产生空行
    lines = text.splitlines()
    if not lines:
        _fail("表头缺失：文件为空")

    header = lines[0].split("\t")
    if len(header) < 2:
        _fail("表头缺失：至少需要基因 ID 列与一个细胞 ID 列")
    cell_ids = header[1:]
    if any(cell == "" for cell in cell_ids):
        _fail("表头存在空细胞 ID")
    if len(set(cell_ids)) != len(cell_ids):
        dup = _first_duplicate(cell_ids)
        _fail(f"细胞 ID 重复：{dup!r}")

    gene_ids: List[str] = []
    counts: List[List[int]] = []
    seen_genes = set()
    n_cells = len(cell_ids)

    for offset, line in enumerate(lines[1:], start=2):
        if line == "":
            _fail(f"第 {offset} 行为空，无法解析")
        fields = line.split("\t")
        if len(fields) != n_cells + 1:
            _fail(
                f"第 {offset} 行列数为 {len(fields) - 1}，"
                f"与表头细胞数 {n_cells} 不一致"
            )
        gene_id = fields[0]
        if gene_id == "":
            _fail(f"第 {offset} 行基因 ID 为空")
        if gene_id in seen_genes:
            _fail(f"基因 ID 重复：{gene_id!r}")
        seen_genes.add(gene_id)
        row = [
            _parse_count(fields[c + 1], gene_id, cell_ids[c], offset)
            for c in range(n_cells)
        ]
        gene_ids.append(gene_id)
        counts.append(row)

    if not gene_ids:
        _fail("空矩阵：没有任何基因数据行")

    total = 0
    for row in counts:
        total += sum(row)

    return ExpressionMatrix(
        gene_ids=gene_ids,
        cell_ids=cell_ids,
        counts=counts,
        sha256=digest,
        path=path,
        total_counts=total,
    )


def _first_duplicate(values: List[str]) -> str:
    seen = set()
    for value in values:
        if value in seen:
            return value
        seen.add(value)
    return values[0]

"""``cell-flow`` 命令行入口。

用法::

    cell-flow analyze --input <表达矩阵.tsv|mtx目录> --output-dir <结果目录> \\
        [--input-format tsv|mtx] \\
        [--min-genes 200] [--max-mito-fraction 0.2] [--min-cells 3] \\
        [--mito-prefix MT-] [--n-hvg 2000] [--n-clusters 2|auto] [--seed 20240617]
"""

import sys
from typing import Optional, Sequence

from . import __version__
from .errors import CellFlowError
from .pca import MAX_PCS
from .pipeline import DEFAULT_SEED, Config, INPUT_FORMATS, run

USAGE = (
    "用法：cell-flow analyze --input <表达矩阵.tsv|mtx目录> --output-dir <结果目录>\n"
    "                [--input-format tsv|mtx]\n"
    "                [--min-genes N] [--max-mito-fraction F] [--min-cells N]\n"
    "                [--mito-prefix PREFIX] [--n-hvg N] [--n-pcs N]\n"
    "                [--n-clusters N|auto] [--seed N]\n"
    "      cell-flow --version"
)


def _fail_usage(message: str) -> "CellFlowError":
    # 延迟导入以避免循环引用
    from .errors import CellFlowConfigError

    return CellFlowConfigError(f"{message}\n{USAGE}")


def _parse_int(name: str, raw: str) -> int:
    try:
        value = int(raw, 10)
    except (TypeError, ValueError):
        raise _fail_usage(f"参数 {name} 需要整数，得到 {raw!r}")
    return value


def _parse_float(name: str, raw: str) -> float:
    try:
        value = float(raw)
    except (TypeError, ValueError):
        raise _fail_usage(f"参数 {name} 需要数值，得到 {raw!r}")
    if value != value or value in (float("inf"), float("-inf")):
        raise _fail_usage(f"参数 {name} 必须是有限数值，得到 {raw!r}")
    return value


def _parse_n_clusters(raw: str):
    # auto（逐字小写）启用自动选择；其余取值仍按整数解析，<2 由 validate_config 拒绝
    if raw == "auto":
        return "auto"
    return _parse_int("--n-clusters", raw)


def _build_analyze_config(options: dict) -> Config:
    if options.get("input") is None:
        raise _fail_usage("缺少必需参数 --input")
    if options.get("output_dir") is None:
        raise _fail_usage("缺少必需参数 --output-dir")
    return Config(
        input_path=options["input"],
        output_dir=options["output_dir"],
        min_genes=_parse_int("--min-genes", options["min_genes"]),
        max_mito_fraction=_parse_float(
            "--max-mito-fraction", options["max_mito_fraction"]
        ),
        min_cells=_parse_int("--min-cells", options["min_cells"]),
        mito_prefix=options["mito_prefix"],
        n_hvg=_parse_int("--n-hvg", options["n_hvg"]),
        n_pcs=_parse_int("--n-pcs", options["n_pcs"]),
        n_clusters=_parse_n_clusters(options["n_clusters"]),
        seed=_parse_int("--seed", options["seed"]),
        input_format=_parse_input_format(options["input_format"]),
    )


def _parse_input_format(raw: str) -> str:
    if raw not in INPUT_FORMATS:
        raise _fail_usage(
            f"--input-format 只能是 tsv 或 mtx，得到 {raw!r}"
        )
    return raw


def _parse_analyze(argv: Sequence[str]) -> Config:
    # argparse 的退出码是 2，与本工具“配置错误退出 3”冲突，故自行做确定解析
    value_options = {
        "--input": "input",
        "--output-dir": "output_dir",
        "--input-format": "input_format",
        "--min-genes": "min_genes",
        "--max-mito-fraction": "max_mito_fraction",
        "--min-cells": "min_cells",
        "--mito-prefix": "mito_prefix",
        "--n-hvg": "n_hvg",
        "--n-pcs": "n_pcs",
        "--n-clusters": "n_clusters",
        "--seed": "seed",
    }
    options = {
        "input_format": "tsv",
        "min_genes": "200",
        "max_mito_fraction": "0.2",
        "min_cells": "3",
        "mito_prefix": "MT-",
        "n_hvg": "2000",
        "n_pcs": str(MAX_PCS),
        "n_clusters": "2",
        "seed": str(DEFAULT_SEED),
    }

    index = 0
    while index < len(argv):
        token = argv[index]
        if token.startswith("--") and "=" in token:
            key, raw_value = token.split("=", 1)
            if key not in value_options:
                raise _fail_usage(f"未知参数 {key}")
            options[value_options[key]] = raw_value
            index += 1
            continue
        if token in value_options:
            if index + 1 >= len(argv):
                raise _fail_usage(f"参数 {token} 缺少取值")
            options[value_options[token]] = argv[index + 1]
            index += 2
            continue
        raise _fail_usage(f"无法识别的参数或多余位置参数：{token}")

    return _build_analyze_config(options)


def main(argv: Optional[Sequence[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]

    if not argv:
        message = _fail_usage("缺少子命令")
        print(f"cell-flow: 错误: {message}", file=sys.stderr)
        return message.exit_code
    if argv[0] in ("-h", "--help"):
        print(USAGE)
        return 0
    if argv[0] in ("-V", "--version"):
        print(f"cell-flow {__version__}")
        return 0
    if argv[0] != "analyze":
        message = _fail_usage(f"未知子命令 {argv[0]!r}")
        print(f"cell-flow: 错误: {message}", file=sys.stderr)
        return message.exit_code

    if any(token in ("-h", "--help") for token in argv[1:]):
        print(USAGE)
